package online.springshop.api.modules.auth.domain.useraction.valueobject;

import lombok.Getter;

/**
 * Wraps a confirmation code that has already been encoded by an external
 * encoder. This value object does not encode or hash the code itself.
 */
public final class EncodedConfirmationCode
{
    @Getter
    private final String value;

    private EncodedConfirmationCode (String value)
    {
        this.value = value;
    }

    /**
     * Creates an encoded confirmation code from a value generated by an encoder
     * inside the API.
     *
     * @param value the API-generated encoded value
     * @return a wrapper around the encoded confirmation code
     * @throws NullPointerException when the generated value is {@code null}
     * @throws IllegalArgumentException when the generated value is blank
     */
    public static EncodedConfirmationCode from (String value)
    {
        if (value == null)
            throw new NullPointerException("Encoded confirmation code must not be null");

        if (value.isBlank())
            throw new IllegalArgumentException("Encoded confirmation code must not be blank");

        return new EncodedConfirmationCode(value);
    }

    @Override
    public boolean equals (Object object)
    {
        if (this == object)
            return true;

        if (!(object instanceof EncodedConfirmationCode that))
            return false;

        return value.equals(that.value);
    }

    @Override
    public int hashCode ()
    {
        return value.hashCode();
    }
}
